const CACHE='astroctopi-v1.3';
const ASSETS=["./", "./index.html", "./style.css", "./appearance.css", "./appearance.js", "./sos.js", "./sos.css", "./desktop-guide.js", "./app.js", "./core.js", "./art.js", "./sections.js", "./manifest.webmanifest", "./assets/icon-192.png", "./assets/icon-512.png", "./assets/fonts/dm-sans-400.ttf", "./assets/fonts/dm-sans-500.ttf", "./assets/fonts/dm-sans-600.ttf", "./assets/fonts/dm-sans-700.ttf", "./assets/fonts/outfit-400.ttf", "./assets/fonts/outfit-500.ttf", "./assets/fonts/outfit-600.ttf", "./assets/fonts/outfit-700.ttf"];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS))));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k))))));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok&&ASSETS.some(a=>new URL(a,self.location.href).href===event.request.url)){const copy=response.clone();caches.open(CACHE).then(c=>c.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request)));});
